CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS team_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS team_users(id TEXT PRIMARY KEY,name TEXT NOT NULL,token TEXT UNIQUE NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS team_access_identities(issuer TEXT NOT NULL,subject TEXT NOT NULL,actor TEXT NOT NULL REFERENCES team_users(id),PRIMARY KEY(issuer,subject));
CREATE TABLE IF NOT EXISTS team_pools(id TEXT PRIMARY KEY,name TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('private','shared')));
CREATE TABLE IF NOT EXISTS team_members(pool TEXT NOT NULL REFERENCES team_pools(id),actor TEXT NOT NULL REFERENCES team_users(id),role TEXT NOT NULL CHECK(role IN('owner','writer','reader')),PRIMARY KEY(pool,actor));
CREATE INDEX IF NOT EXISTS team_members_actor ON team_members(actor,pool);
CREATE TABLE IF NOT EXISTS team_memories(pool TEXT NOT NULL REFERENCES team_pools(id),id TEXT NOT NULL,body TEXT NOT NULL,contributor TEXT NOT NULL REFERENCES team_users(id),created TEXT NOT NULL,PRIMARY KEY(pool,id));
CREATE TABLE IF NOT EXISTS team_origins(pool TEXT NOT NULL,id TEXT NOT NULL,origin TEXT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(pool,id,origin),FOREIGN KEY(pool,id) REFERENCES team_memories(pool,id));
CREATE TABLE IF NOT EXISTS team_vectors(pool TEXT NOT NULL,id TEXT NOT NULL,model TEXT NOT NULL,backend TEXT NOT NULL,vector vector NOT NULL,PRIMARY KEY(pool,id,model,backend),FOREIGN KEY(pool,id) REFERENCES team_memories(pool,id));
CREATE INDEX IF NOT EXISTS team_vectors_model ON team_vectors(pool,model,backend);
CREATE TABLE IF NOT EXISTS shares(id TEXT PRIMARY KEY,body TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)));
CREATE TABLE IF NOT EXISTS team_shares(id TEXT PRIMARY KEY REFERENCES shares(id),pool TEXT NOT NULL REFERENCES team_pools(id),creator TEXT NOT NULL REFERENCES team_users(id),ids TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS team_shares_pool ON team_shares(pool,creator);
CREATE TABLE IF NOT EXISTS team_policies(actor TEXT NOT NULL REFERENCES team_users(id),pool TEXT NOT NULL REFERENCES team_pools(id),scope TEXT NOT NULL,context TEXT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(actor,pool,scope,context));
CREATE TABLE IF NOT EXISTS challenges(share TEXT NOT NULL REFERENCES shares(id),email TEXT NOT NULL,digest TEXT NOT NULL,expires BIGINT NOT NULL,attempts INTEGER NOT NULL,sent BIGINT NOT NULL,"window" BIGINT NOT NULL,sends INTEGER NOT NULL,PRIMARY KEY(share,email));
CREATE TABLE IF NOT EXISTS access(digest TEXT PRIMARY KEY,share TEXT NOT NULL REFERENCES shares(id),email TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS access_expiry ON access(expires);
CREATE TABLE IF NOT EXISTS revisions(share TEXT NOT NULL REFERENCES shares(id),saved BIGINT NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_attempts(id TEXT PRIMARY KEY,actor TEXT NOT NULL,share TEXT NOT NULL,email TEXT NOT NULL,status TEXT NOT NULL,created BIGINT NOT NULL,message TEXT,claimed BIGINT);
CREATE UNIQUE INDEX IF NOT EXISTS delivery_share_email ON delivery_attempts(share,email);
CREATE INDEX IF NOT EXISTS delivery_pending ON delivery_attempts(status,created);
CREATE TABLE IF NOT EXISTS delivery_quota(scope TEXT NOT NULL,created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS delivery_quota_scope ON delivery_quota(scope,created);
CREATE INDEX IF NOT EXISTS delivery_quota_time ON delivery_quota(created);
CREATE TABLE IF NOT EXISTS verification_quota(scope TEXT NOT NULL,created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS verification_quota_scope ON verification_quota(scope,created);
CREATE INDEX IF NOT EXISTS verification_quota_time ON verification_quota(created);

CREATE TABLE IF NOT EXISTS verification_limits(bucket TEXT PRIMARY KEY,"window" BIGINT NOT NULL,count INTEGER NOT NULL);
